namespace zkgpt::r7::master3 {
namespace {
std::string gen(){static std::string d=[](){Writer w;w.text(hyrax_a3::suite);w.text("MCL-BN254-y2=x3+2-Fr-v1");for(auto&g:hyrax_a3::generators(1024))w.point(g);w.point(parameters(1).scalar);w.point(parameters(1).hiding);return hex(r1::hash(w.b));}();return d;}
void specBytes(Writer&w,const Spec&s){w.text(suite);w.text(hyrax_a3::messageVersion);w.text(s.layout);w.text(s.profile);w.text(s.scope);w.text(s.generators);for(auto n:{s.actual,s.N,s.rows,s.columns})w.number(n,8);}
void exactWrite(int fd,const Bytes&b){std::size_t i=0;while(i<b.size()){auto n=write(fd,b.data()+i,b.size()-i);if(n<0 && errno==EINTR)continue;need(n>0,"M3 private cache write");i+=n;}}
}
void validate(const Spec&s){need(s.N>0 && s.N<=(1u<<24) && !(s.N&(s.N-1)) && s.N>=4096 && s.columns==1024 && s.rows==s.N/1024 && s.actual>0 && s.actual<=s.N,"M3 streaming dimensions");need(s.layout.size()==64 && s.profile==r5b::profileHash() && s.generators==gen() && (s.scope=="Base-Master-prefix" || s.scope=="FC-source-projection"),"M3 streaming layout/profile/generator identity");}
Spec makeSpec(const Layout&l,std::size_t N,bool projection){validate(l);need(N==4096 || N==65536 || N==(1u<<20) || N==(1u<<24),"M3 tested scale whitelist");need(!projection || N==4096,"M3 bounded projection size");Spec s;s.actual=projection?l.projection.size():std::min<std::size_t>(N,l.actual);s.N=N;s.rows=N/1024;s.layout=scopeDigest(l,N,projection);s.profile=l.profile;s.generators=gen();s.scope=projection?"FC-source-projection":"Base-Master-prefix";validate(s);return s;}
Bytes encodeMaster(const Master&m){validate(m.spec);need(m.rows.size()==m.spec.rows,"M3 row count");Writer w;specBytes(w,m.spec);for(auto&p:m.rows)w.point(p);return w.b;}
Master decodeMaster(const Bytes&b,const Spec&expected){validate(expected);Reader r{b};need(r.text()==suite && r.text()==hyrax_a3::messageVersion,"M3 unknown suite/version");Master m;m.spec.layout=r.text();m.spec.profile=r.text();m.spec.scope=r.text();m.spec.generators=r.text();m.spec.actual=r.number(8);m.spec.N=r.number(8);m.spec.rows=r.number(8);m.spec.columns=r.number(8);Writer x,y;specBytes(x,m.spec);specBytes(y,expected);need(x.b==y.b,"M3 untrusted layout/dimensions");for(std::size_t i=0;i<expected.rows;++i)m.rows.push_back(r.point());r.end();need(encodeMaster(m)==b,"M3 noncanonical descriptor");return m;}
std::string identity(const Master&m){return hex(r1::hash(encodeMaster(m)));}
G1 masterMSM(const G1*g,const Fr*x,std::size_t size){
 need(g && x && size>0 && size<=16384,"M3 streaming MSM shape");
 // MCL exposes mutable base storage: retain a bounded private work copy.
 // Scalars are const in MCL, so borrow them without a second allocation.
 thread_local std::vector<G1>scratch(1024);
 G1 out;out.clear();for(std::size_t at=0;at<size;at+=1024){auto n=std::min<std::size_t>(1024,size-at);std::copy_n(g+at,n,scratch.begin());MSMTrace trace(n);G1 p;G1::mulVec(p,scratch.data(),x+at,n);out+=p;auto&m=metrics();++m.msm_calls;m.msm_terms+=n;m.max_msm=std::max<std::uint64_t>(m.max_msm,n);}return out;
}
G1 masterMSM(const std::vector<G1>&g,const std::vector<Fr>&x){need(g.size()==x.size(),"M3 streaming MSM shape");return masterMSM(g.data(),x.data(),g.size());}
Secret commitMaster(const Spec&s,const Value&value){validate(s);Secret out;out.public_pc.spec=s;out.value=value;auto g=hyrax_a3::generators(1024);out.public_pc.rows.reserve(s.rows);out.blinds.reserve(s.rows);for(std::size_t i=0;i<s.rows;++i){std::vector<Fr>row;row.reserve(1024);for(std::size_t j=0;j<1024;++j){auto k=i+s.rows*j;auto f=k<s.actual?value(k):Fr(0);need(f.isValid(),"M3 invalid scalar");row.push_back(f);}OSRandom rng;out.blinds.push_back(rng.scalar());out.public_pc.rows.push_back(masterMSM(g,row)+parameters(1).hiding*out.blinds.back());}return out;}
bool registrationSupported(const Spec&s){return s.N<=65536;}
void registerMaster(IO&io,const Master&m,const Secret*secret){need(registrationSupported(m.spec),"M3 full registration INCOMPLETE transport budget");bindPublic(io,"M3/registration/identity",encodeMaster(m));auto g=hyrax_a3::generators(1024);for(std::size_t i=0;i<m.spec.rows;++i){auto label="M3/registration/row/"+std::to_string(i);const auto active=i>=m.spec.actual?0:std::min<std::size_t>(1024,1+(m.spec.actual-1-i)/m.spec.rows);need(active>0,"M3 empty logical row unsupported");std::vector<G1>bases(g.begin(),g.begin()+active);std::vector<Fr>d;Fr rho=0;Writer first;OSRandom rng;if(io.prover()){need(secret && secret->blinds.size()==m.spec.rows,"M3 private registration shape");for(std::size_t j=0;j<active;++j)d.push_back(rng.scalar());rho=rng.scalar();first.point(masterMSM(bases,d)+parameters(1).hiding*rho);}auto bytes=io.message(label+"/mask",first.b);Reader r{bytes};auto D=r.point();r.end();auto c=io.coin(label+"/c");Writer response;if(io.prover()){for(std::size_t j=0;j<active;++j)response.scalar(d[j]+c*secret->value(i+m.spec.rows*j));response.scalar(rho+c*secret->blinds[i]);}bytes=io.message(label+"/response",response.b);Reader rr{bytes};std::vector<Fr>z;for(std::size_t j=0;j<active;++j)z.push_back(rr.scalar());auto blind=rr.scalar();rr.end();if(!io.prover())need(masterMSM(bases,z)+parameters(1).hiding*blind==D+m.rows[i]*c,"M3 row knowledge/zero-tail equation failed");}}
namespace {hyrax_a3::DotWitness fold(const Secret&s,const std::vector<Fr>&L){hyrax_a3::DotWitness w;w.values.assign(1024,Fr(0));for(std::size_t j=0;j<1024;++j)for(std::size_t i=0;i<s.public_pc.spec.rows;++i){auto k=i+s.public_pc.spec.rows*j;if(k<s.public_pc.spec.actual)w.values[j]+=L[i]*s.value(k);}for(std::size_t i=0;i<L.size();++i)w.blind+=L[i]*s.blinds.at(i);return w;}}
Fr evaluate(const Secret&s,const std::vector<Fr>&point){need(point.size()==r1::log2exact(s.public_pc.spec.N),"M3 MLE dimension");auto d=r1::log2exact(s.public_pc.spec.rows);auto L=r1::weights({point.begin(),point.begin()+d});auto a=r1::weights({point.begin()+d,point.end()});return r1::dot(fold(s,L).values,a);}
void openMaster(IO&io,const Master&m,const Query&q,const Secret*secret,const Hidden*evaluation,Random*rng,const std::string&id){validate(m.spec);validate(q.evaluation,io.session(),q.evaluation.role);need(q.point.size()==r1::log2exact(m.spec.N) && !id.empty(),"M3 opening query/id");Writer b;b.text(suite);b.text(identity(m));b.text(m.spec.layout);b.text(io.session());b.text(id);auto parent=io.prefix();b.raw(Bytes(parent.begin(),parent.end()));b.raw(encode(q.evaluation));for(auto&r:q.point)b.scalar(r);bindPublic(io,"M3/open/"+id+"/binding",b.b);auto d=r1::log2exact(m.spec.rows);auto L=r1::weights({q.point.begin(),q.point.begin()+d});auto a=r1::weights({q.point.begin()+d,q.point.end()});auto xi=masterMSM(m.rows,L);hyrax_a3::DotWitness w;if(io.prover()){need(secret && evaluation && rng && encodeMaster(secret->public_pc)==encodeMaster(m),"M3 opening private identity");w=fold(*secret,L);w.evaluation=*evaluation;}stage2::ScopedIO scoped(io,"M3/open/"+id);hyrax_a3::dotProduct(scoped,xi,q.evaluation,a,io.prover()?&w:nullptr,rng);}
MappedValues::MappedValues(int fd){struct stat s{};need(fd>2 && fstat(fd,&s)==0 && S_ISREG(s.st_mode) && s.st_uid==getuid() && (s.st_mode&077)==0 && s.st_size==std::int64_t(16642424)*32 && (fcntl(fd,F_GETFL)&O_ACCMODE)==O_RDONLY,"M3 private base cache FD");bytes_=s.st_size;auto p=mmap(nullptr,bytes_,PROT_READ,MAP_PRIVATE,fd,0);need(p!=MAP_FAILED,"M3 private mmap failed");data_=static_cast<const std::uint8_t*>(p);}
MappedValues::~MappedValues(){if(data_)munmap(const_cast<std::uint8_t*>(data_),bytes_);}
Fr MappedValues::at(std::size_t i)const{need(i<bytes_/32,"M3 private source index");Fr x;need(x.deserialize(data_+32*i,32)==32 && x.isValid(),"M3 private scalar encoding");return x;}
void cacheValues(int fd,const std::vector<Fr>&v){struct stat s{};need(fd>2 && fstat(fd,&s)==0 && S_ISREG(s.st_mode) && s.st_uid==getuid() && (s.st_mode&077)==0 && s.st_size==0 && v.size()==16642424,"M3 private cache target");Bytes block;block.reserve(32768);for(auto&x:v){auto b=r1::encode(x);block.insert(block.end(),b.begin(),b.end());if(block.size()==32768){exactWrite(fd,block);block.clear();}}if(!block.empty())exactWrite(fd,block);}
}
